import{_ as t,c as n,o as s,j as e,a as l}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"易传灯","description":"易传灯 - 易传灯","frontmatter":{"title":"易传灯","description":"易传灯 - 易传灯"},"headers":[],"relativePath":"zh/classics/yichuandeng/001.md","filePath":"zh/classics/yichuandeng/001.md"}'),r={name:"zh/classics/yichuandeng/001.md"};function c(i,a,o,d,p,u){return s(),n("div",null,[...a[0]||(a[0]=[e("h1",{id:"易传灯",tabindex:"-1"},[l("易传灯 "),e("a",{class:"header-anchor",href:"#易传灯","aria-label":"Permalink to “易传灯”"},"​")],-1),e("p",null,"有序 是书旧署徐总干撰，而不著名。其子序谓其父尝师事吕祖谦、唐仲友，所学似尚有禀承。顾取释氏传灯语为经解标题，谬盩甚矣。其言君子小人吉凶阴阳之义，颇有阐发，而所论河图数象，牵附九宫，则又乖于正道。盖其书纯驳参半，乃指斥后学差误，得无责人则明，而责己则昏欤？以其裒辑于散帙之中，亦云希觏，录备四库，庶几瑕瑜不掩。系诗简端讥之，正所以惜之也。",-1),e("p",null,"徐氏隐名，故以何标题，想亦自知过。本来画卦由古圣，胡乃传灯拟梵陀。学述东莱道未见，习沿永叔语伤讹。明云后学多差误，可识其人差已多。钦定四库全书经部一易传灯四卷易类提要",-1),e("p",null,"臣 等谨案：易传灯一书，诸家书目俱不著录，朱彝尊经义考亦不载其名。惟永乐大典散见于谷卦之中，题其官曰徐总干，而不著名字。又载其子子东序，谓其父尝师事吕祖谦、唐仲友。考宋史，徐侨尝受业于吕祖谦，著读易记、尚书括旨等书。祖谦门人又有徐侃、徐倬序，无明文，不能定其为谁也。「传灯」本释氏之语，乃取之以名经解，殊为乖刺。又谓系词下传「易之为书」三章，皆汉儒易纬之文，讹为夫子之作，以诳后世，亦沿欧阳修之误。又谓圣人观河图有数有象，以从横十五之妙，配乾坤九六之数，白紫者吉，黄黑者凶。是直以易数为五行家言，尤未免于驳杂。然其八卦总论十六篇，参互以求，颇能得易之类例。如曰大壮、大有、夬、乾，乾在乾、兑、离、震之下者也。乾九三曰「君子」，而余卦九三皆有「君子」「小人」之词，以君子在重刚中，君子则吉，小人则凶，故分别言之也。其处于巽、坎、艮、坤之下者，曰小畜、大畜、需、泰，凡九三上遇阴爻，皆有畏谨之义，剖析更为微细。又谓易之取象，该三代制度。如比九五言「王用三驱」，见王田不合围，三面而驱之礼。巽九二言「史巫纷若」，见古有太史、男巫、女巫之制。论易、礼之相通，亦有证据。盖一知半解，可取者亦颇不乏。虽有丝麻，无弃菅蒯，固说易者之所旁采尔。乾隆四十六年九月恭校上。",-1),e("p",null,"总纂官 臣 纪昀、 臣 陆锡熊、 臣 孙士毅，总校官 臣 陆费墀。原序",-1),e("p",null,"先君总干幼年习声律，自后喜经术而厌雕篆，由是再更六典。绍兴初，尝师东莱吕先生 祖谦、 说斋唐先生 仲友。 从宋先生 真卿 书堂，因见壁间伏羲先天八卦图象，笃志学易，佩服师训，蚤夜究心。尝应试漕闱，两预荐书，皆以是经。先君重道义而轻利禄，薄奔竞而安恬退，隐居易堂，精研先天之学，以六十四卦三百八十四爻系国家兴衰治乱之时用。宝庆间，遂作周易大义，继作衍义，续作传灯，究先哲之微言，期后学于同归。去「爻应互体」等说，越数十载方脱稿。先君初意，为子孙众多，皆欲淑以斯文，故作是书，非欲自侈其学也。愚不敢私，即取而公之，悉锓诸梓，不惟不秘先君之志，而先君之学亦于是乎传矣。宝祐丁巳仲春既望，季子徐子东敬系。",-1)])])}const _=t(r,[["render",c]]);export{m as __pageData,_ as default};
